val LoTEClientTest by testSuite {

    data class Context(
        val mockEngine: MockEngine,
        val client: LoTEClient,
    )

    fun setup(): Context {
        val mockEngine = MockEngine { request ->
            val requestedUrl = request.url.toString().substringBefore("?")

            val responsePayload = when (requestedUrl) {
                "https://acceptance.trust.tech.ec.europa.eu/lists/eudiw/pid-providers.json" -> PID_PROVIDERS_JWS
                "https://acceptance.trust.tech.ec.europa.eu/lists/eudiw/wallet-providers.json" -> WALLET_PROVIDERS_JWS
                "https://acceptance.trust.tech.ec.europa.eu/lists/eudiw/wrpac-providers.json" -> WRPAC_PROVIDERS_JWS
                "https://acceptance.trust.tech.ec.europa.eu/lists/eudiw/mdl-providers.json" -> MDL_PROVIDERS_JWS
                else -> null
            }

            if (responsePayload != null) {
                respond(
                    content = ByteReadChannel(responsePayload),
                    status = HttpStatusCode.OK,
                    headers = headersOf(HttpHeaders.ContentType, MediaTypes.Application.JSON)
                )
            } else {
                respond(
                    content = ByteReadChannel("Not Found"),
                    status = HttpStatusCode.NotFound
                ).also { Napier.w("LoTE Mock Engine: URL NOT MATCHED $requestedUrl") }
            }
        }

        return Context(
            mockEngine = mockEngine,
            client = LoTEClient(
                engine = mockEngine,
                verifyJwsObject = VerifyJwsObject()
            )
        )
    }

    listOf(
        "https://acceptance.trust.tech.ec.europa.eu/lists/eudiw/pid-providers.json" to "PID Providers Acceptance",
        "https://acceptance.trust.tech.ec.europa.eu/lists/eudiw/wallet-providers.json" to "Wallet Providers Acceptance",
        "https://acceptance.trust.tech.ec.europa.eu/lists/eudiw/wrpac-providers.json" to "WRPAC Providers Acceptance",
        "https://acceptance.trust.tech.ec.europa.eu/lists/eudiw/mdl-providers.json" to "mDL Providers Acceptance",
    ).forEach { (url, listName) ->

        test("fetch and validate trust list: $listName") {
            with(setup()) {
                val result = client.fetchTrustList(url)

                result.isSuccess shouldBe true

                val lote = result.getOrThrow()
                lote.trustedEntitiesList shouldNotBe null
            }
        }
    }
}